    'work.wordpopi.segment.5.tag': 'Chế độ 1',
    'work.wordpopi.segment.5.name': 'Thẻ ghi nhớ',
    'work.wordpopi.segment.5.desc': 'Lật mặt trước/sau theo nhịp độ riêng với đánh giá độ khó rõ ràng (Lại / Khó / Tốt / Dễ). Phiên âm IPA, câu ví dụ và âm thanh bản ngữ trên mỗi thẻ. Lịch trình thích ứng dựa trên độ khó được đánh giá.',
    'work.wordpopi.segment.6.tag': 'Chế độ 2',
    'work.wordpopi.segment.6.name': 'Trắc nghiệm',
    'work.wordpopi.segment.6.desc': 'Câu hỏi bốn lựa chọn với "phương án gây nhiễu thông minh" — đáp án sai có liên quan ngữ nghĩa với từ mục tiêu, không ngẫu nhiên. Buộc phân biệt giữa các từ có cùng ngữ cảnh.',
    'work.wordpopi.segment.7.tag': 'Chế độ 3',
    'work.wordpopi.segment.7.name': 'Phát âm',
    'work.wordpopi.segment.7.desc': 'Nghe từ, xác định từ đó trong các lựa chọn. Rèn luyện nhận dạng âm thanh độc lập với đọc. Dùng text-to-speech chất lượng bản ngữ với ngữ âm phù hợp cho tiếng Hàn và tiếng Thái.',
    'work.wordpopi.segment.8.tag': 'Chế độ 4',
    'work.wordpopi.segment.8.name': 'Chính tả',
    'work.wordpopi.segment.8.desc': 'Gõ từ dựa trên định nghĩa — tác vụ ghi nhớ sâu nhất. Có giá trị nhất cho sự lưu loát khi tạo ra ngôn ngữ. Thuật toán thích ứng ưu tiên luyện chính tả nhiều hơn cho các từ được đánh dấu yếu ở chế độ khác.',
    'work.wordpopi.metric.4': 'Không cần server — MultipeerConnectivity qua Wi-Fi cục bộ',
