    'work.wordpopi.metric.6': 'Multiplayer offline hoạt động không cần kết nối internet',
    'work.wordpopi.segment.9.tag': 'Đã ra mắt',
    'work.wordpopi.segment.9.name': 'Bốn chế độ học',
    'work.wordpopi.segment.9.desc': 'Thẻ ghi nhớ, trắc nghiệm, nhận dạng phát âm, chính tả — tất cả thích ứng, tất cả trên cùng một bộ thẻ',
    'work.wordpopi.segment.10.tag': 'Đã ra mắt',
    'work.wordpopi.segment.10.name': 'Hơn 1.000 từ được tuyển chọn',
    'work.wordpopi.segment.10.desc': '20 bộ thẻ chủ đề gồm Kinh doanh, Du lịch, Khoa học, Tâm lý học, Luật và nhiều hơn — sẵn sàng học ngay khi cài đặt',
