    'work.great2know.meta.engagement': 'Bán thời gian',
    'work.great2know.heroCaption': 'great2know — nền tảng chuyển giao tri thức tập trung cho các đợt chuyển đổi nhân sự doanh nghiệp',
    'work.great2know.metric.1': 'Module nền tảng cốt lõi được thiết kế từ đầu',
    'work.great2know.metric.2': 'Loại người dùng khác biệt với nhu cầu và mô hình tư duy khác nhau',
    'work.great2know.metric.3': 'Sản phẩm hoàn chỉnh xây dựng từ ý tưởng đến trải nghiệm ra mắt',
    'work.great2know.pullquote.1': 'Thách thức thiết kế không phải là làm cho việc chuyển giao tri thức trở nên dễ dàng. Mà là làm cho nó trở thành điều tất yếu — gắn quy trình chuyển giao sâu vào luồng chuyển đổi đến mức bỏ qua nó còn khó hơn là thực hiện nó.',
    'work.great2know.phase.1.title': 'Ghi nhận',
    'work.great2know.phase.1.desc': 'Mẫu có cấu trúc và gợi ý theo ngữ cảnh hướng dẫn người gửi tri thức ghi lại quy trình, quyết định và mối quan hệ mà không cần họ biết trước điều gì quan trọng nhất.',
    'work.great2know.phase.2.title': 'Cấu trúc hoá',
    'work.great2know.phase.2.desc': 'Tri thức đã ghi nhận được tổ chức theo mô hình phân loại — chủ đề, vai trò và mức độ khẩn cấp — để người chưa biết mình cần tìm gì vẫn điều hướng được.',
    'work.great2know.phase.3.title': 'Chuyển giao',
    'work.great2know.phase.3.desc': 'Trải nghiệm cho người nhận hiển thị tri thức liên quan theo đúng trình tự — định hướng vai trò trước, rồi đến chiều sâu vận hành, rồi các trường hợp ngoại lệ và ký ức tổ chức.',
    'work.great2know.phase.4.title': 'Xác minh',
    'work.great2know.phase.4.desc': 'Phân tích dành cho quản lý cho thấy mức độ hoàn thành chuyển giao, khoảng trống nội dung và chuẩn thời gian đạt năng suất — biến một quy trình vô hình thành có thể đo lường được.',
    'work.great2know.segment.1.tag': 'Module',
    'work.great2know.segment.1.name': 'Kho tri thức',
    'work.great2know.segment.1.desc': 'Ghi nhận và tổ chức tập trung thông tin vai trò quan trọng theo chủ đề và mức độ khẩn cấp — có cấu trúc cho cả người gửi nhập liệu lẫn người nhận điều hướng',
    'work.great2know.segment.2.tag': 'Module',
    'work.great2know.segment.2.name': 'Tổng quan vai trò',
    'work.great2know.segment.2.desc': 'Mẫu bàn giao có cấu trúc cho thấy mỗi vai trò sở hữu, biết và làm gì — giúp nhân viên mới có bức tranh đầy đủ về vai trò trước ngày đầu tiên',
    'work.great2know.segment.3.tag': 'Module',
    'work.great2know.segment.3.name': 'Phân tích chuyển đổi',
    'work.great2know.segment.3.desc': 'Theo dõi mức độ hoàn thành, xác định khoảng trống nội dung và chuẩn năng suất — cho quản lý khả năng quan sát tiến độ chuyển giao mà không cần vi quản lý',
    'work.great2know.segment.4.tag': 'Module',
    'work.great2know.segment.4.name': 'Luồng onboarding',
    'work.great2know.segment.4.desc': 'Trải nghiệm dẫn dắt cho người nhận tri thức — phân phối nội dung theo trình tự, hiển thị đúng thông tin ở đúng giai đoạn onboarding',
    'work.great2know.caption.modules': 'Kho tri thức và phân tích chuyển đổi — hai trong bốn module cốt lõi của nền tảng',
    'work.great2know.metric.4': 'Rủi ro mất tri thức trong quá trình chuyển đổi nhân sự',
    'work.great2know.metric.4.value': 'Giảm',
