// ─── Engine ──────────────────────────────────────────────────────────────────
const DEFAULT_LANG = 'en';

function getLang() {
  return localStorage.getItem('lang') || DEFAULT_LANG;
}

function t(key, lang) {
  const l = lang || getLang();
  return (TRANSLATIONS[l] && TRANSLATIONS[l][key]) || (TRANSLATIONS[DEFAULT_LANG] && TRANSLATIONS[DEFAULT_LANG][key]) || key;
}

function applyTranslations(lang) {
  document.documentElement.lang = lang;

  // Text content
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    const val = t(key, lang);
    if (val !== key) el.textContent = val;
  });

  // Inner HTML (for elements with nested markup)
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    const key = el.getAttribute('data-i18n-html');
    const val = t(key, lang);
    if (val !== key) el.innerHTML = val;
  });

  // aria-label
  document.querySelectorAll('[data-i18n-aria]').forEach(el => {
    const key = el.getAttribute('data-i18n-aria');
    const val = t(key, lang);
    if (val !== key) el.setAttribute('aria-label', val);
  });

  // placeholder
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
    const key = el.getAttribute('data-i18n-placeholder');
    const val = t(key, lang);
    if (val !== key) el.setAttribute('placeholder', val);
  });

  // Update lang toggle button label
  document.querySelectorAll('.lang-toggle').forEach(btn => {
    btn.textContent = lang === 'vi' ? 'EN' : 'VI';
    btn.setAttribute('aria-label', lang === 'vi' ? 'Switch to English' : 'Chuyển sang tiếng Việt');
  });
}

function initI18n() {
  const lang = getLang();
  applyTranslations(lang);

  document.querySelectorAll('.lang-toggle').forEach(btn => {
    btn.addEventListener('click', () => {
      const next = getLang() === 'vi' ? 'en' : 'vi';
      localStorage.setItem('lang', next);
      applyTranslations(next);
    });
  });
}

// Run before DOMContentLoaded to minimise flash but querySelectorAll needs DOM
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initI18n);
} else {
  initI18n();
}
